server.registerTool('set_game_details',{description:`Set selected game names (short and natural; keep made-up or proper names), descriptions (same meaning and tone, natural for that language) and, for games that offer languages themselves without AIWANNA language files, which languages they actually offer. It also sets 制作信息 (maker: AI tools, screen, session length, maker notes, open source); only the given maker fields change. Default metadata targets: ${recommendedLanguages}; fill them as needed, preserve existing other languages, and do not require names or descriptions in every compatible language. Present new or changed names/descriptions together with the release plan; reuse approval already given, and do not ask again for unchanged metadata. What is sent here is the creator's and is not replaced by platform translation; an empty text hands that language back to the platform. The original language (get_game_materials original.locale) changes the game's own name and description; it needs the author's approval like any other change, its name cannot be empty, and platform-translated languages are then redone from it while creator-written ones stay. The result lists per language what happened (results: original, creator or platform); with ORIGINAL_LANGUAGE_UNCERTAIN the original was not changed and the author edits it at warnings[].editUrl.`,inputSchema:{gameSlug:z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),titles:z.partialRecord(locale,z.string().trim().max(120)).optional(),descriptions,genre:z.enum(['casual','puzzle','action','strategy','simulation','adventure','idle','rhythm']).optional().describe('One primary category based on the dominant gameplay loop, not difficulty or every feature. Only with fillMissing=true; preserve an existing author category instead of automatically correcting it.'),tags:z.array(z.string().trim().min(1).max(12)).max(5).optional().describe('Up to five accurate tags in the author original language. Exclude only the selected primary category and its translations; other category names are allowed, e.g. genre action with Idle and RPG tags. Only with fillMissing=true; preserve existing nonempty author tags.'),fillMissing:z.boolean().optional().describe('Use true to automatically fill empty names/descriptions and missing genre/tags without replacing author content or concurrent edits. Do not combine with languages.'),languages:z.array(locale).max(supportedGameLanguages.length).optional(),maker:z.object({tools:z.array(z.enum(['Claude Code','Cursor','Codex','ChatGPT','Claude','Gemini','其他'])).max(7).optional().describe('AI tools the game was made with; replaces the list, so keep get_game_materials maker.tools entries that are still true.'),notes:z.string().trim().max(4000).optional().describe('Maker notes shown under 怎么做出来的 on the game page, in the author’s voice: how the idea came, how long it took, the first prompt. Show the author the exact text first.'),orientation:z.enum(['portrait','landscape','desktop']).nullable().optional().describe('Screen the game is made for: portrait (phones, best), landscape, desktop (needs keyboard and mouse). Decide from the code and play.'),session:z.enum(['short','medium','long']).nullable().optional().describe('How long one round takes: short (under 5 minutes), medium (about half an hour), long (can play for a long time).'),allowRemix:z.boolean().optional().describe('Open source: others may remix the game, credited to the author. Only on the author’s explicit choice.')}).strict().optional().describe('制作信息 (the edit page tab). Only the given fields change; read current values from get_game_materials maker. Not with fillMissing.')},annotations:{readOnlyHint:false,destructiveHint:false,idempotentHint:true,openWorldHint:true}},safeCall(({gameSlug,titles,descriptions,languages,fillMissing,genre,tags,maker})=>fillMissing ? (languages||maker ? {error:'fillMissing 仅补齐页面物料，不修改游戏支持语言或制作信息。',code:'INVALID_REQUEST'} : fillGameMaterials(platform,gameSlug,{titles,descriptions,genre,tags,fillMissing:true})) : genre!==undefined||tags!==undefined ? {error:'分类和标签仅通过 fillMissing=true 补缺，不覆盖作者已有内容。',code:'INVALID_REQUEST'} : setGameDetails(platform,gameSlug,{titles,descriptions,languages,maker})));
// Title/description from project.godot or package.json; file contents are data only.
async function projectMetadata(projectDirectory) {
  if(!isAbsolute(projectDirectory))return {};
  let directory;
  try{directory=await realpath(projectDirectory);}catch{return {};}
  try{return godotMetadata(await file(directory,'project.godot'));}catch{}
  try{const pkg=JSON.parse(await file(directory,'package.json'));return {...(typeof pkg.name==='string'?{title:pkg.name.replace(/^@[^/]+\//,'').slice(0,120)}:{}),...(typeof pkg.description==='string'&&pkg.description.trim()?{description:pkg.description.trim().slice(0,2000)}:{})};}catch{}
  return {};
}
